// Administrator-only, on-demand read UI. Opening a record never calls Gemini.
import {escapeAiText as esc} from './ai-classification.js';
const verifiedFields=['work.album_type','work.original_year','work.original_date','work.release_attributes','edition.year','edition.date','edition.label','edition.catalog_number'];
export function researchMarkup(data){
 return data.items.length?data.items.map(r=>`<details class="ai-research-revision"><summary>Revision ${r.revision} · ${esc(r.mode)} · ${esc(r.state)}${r.stale?' · 입력 변경됨':''}</summary><p>${esc(r.model)} · ${esc(new Date(r.created*1000).toLocaleString())}</p><p>외부 검증: ${r.sources.length?'관리자 출처 확인 기록 (아래 필드만)':'미완료 · 모델 지식 또는 입력 단서'}</p><h4>원작 앨범</h4>${Object.entries(r.content.work).map(([k,v])=>`<p><span>${esc(k)}</span> ${esc(v||'미확인')} <small>${esc(r.content.basis['work.'+k]||'unknown')}</small></p>`).join('')}<h4>소장 판본</h4>${Object.entries(r.content.edition).map(([k,v])=>`<p><span>${esc(k)}</span> ${esc(v||'미확인')}</p>`).join('')}<details><summary>유형·최초 발매일·판본·기존값 비교·근거</summary><pre>${esc(JSON.stringify({work:r.proposal.work,edition:r.proposal.edition,comparison:r.comparison,basis:r.proposal.basis,uncertainties:r.proposal.uncertainties,protected_review:r.proposal_review_state,versions:{prompt:r.prompt_version,rules:r.rule_version},fingerprint:r.input_fingerprint},null,2))}</pre></details>${r.sources.map(s=>`<p>${esc(s.field)}${s.verified_value!=null?' = '+esc(JSON.stringify(s.verified_value)):''} · 관리자 확인: ${esc(s.reviewer||'')} · <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a> · ${esc(new Date(s.checked_at*1000).toLocaleString())}</p>`).join('')}<div class="ai-research-actions">${[['confirmed','검토 확정'],['held','보류'],['invalidated','무효화']].map(([a,t])=>`<button data-research-state="${a}" data-id="${esc(r.id)}" ${r.stale&&a==='confirmed'?'disabled':''}>${t}</button>`).join('')}</div><details><summary>관리자 연구 기록 수정 (새 revision)</summary><form data-research-edit data-id="${esc(r.id)}"><textarea name="content" rows="10" maxlength="14500" aria-label="연구 기록 JSON">${esc(JSON.stringify(r.content,null,2))}</textarea><button>새 revision 저장</button></form></details><details><summary>실제로 확인한 출처 기록</summary><form data-research-source data-id="${esc(r.id)}"><select name="field" aria-label="검증 필드">${verifiedFields.map(k=>`<option>${k}</option>`).join('')}${Object.entries(r.content).filter(([k])=>k!=='basis').flatMap(([s,fields])=>Object.keys(fields).map(k=>`<option>${s+'.'+k}</option>`)).join('')}</select><input name="verified_value" maxlength="500" placeholder='확인값 (연도: 2020, 속성: ["Digital Single"], 날짜: 2020-12-16)' aria-label="공식 확인값"><small>분류 필드는 확인값 필수. AI 제안과 운영 DB는 변경하지 않습니다.</small><input name="url" type="url" placeholder="공개 HTTPS 출처 URL (쿼리 제외)" required><input name="title" maxlength="200" placeholder="출처 제목" required><label><input type="checkbox" name="attest" required>이 자료를 직접 확인했습니다.</label><button>출처 확인 기록</button></form></details></details>`).join(''):'<p>AI 연구 기록 없음</p>';
}
export function mountAiResearch({container,albumId,canManage,api}){
 if(!canManage())return ()=>{};
 const doc=container.ownerDocument;
 if(!doc.querySelector('#vinyl-ai-research-css')){const link=doc.createElement('link');link.id='vinyl-ai-research-css';link.rel='stylesheet';link.href=new URL('ai-research.css',doc.baseURI).href;doc.head.append(link);}
 const section=doc.createElement('details');section.className='vinyl-ai-research';
 section.innerHTML='<summary>AI 앨범 연구 기록</summary><p class="ai-research-notice" role="status">펼치면 저장된 기록만 조회합니다.</p><div data-research-items></div><div class="ai-research-actions"><button data-research-refresh>기록 조회</button><button data-research-next hidden>이전 기록</button><button data-deep>심층 연구 요청</button></div><p>연구 요청은 대기열에 정지 상태로 등록됩니다. AI 관리 화면에서 한도 확인 후 시작하세요.</p>';
 container.append(section);const abort=new AbortController();let disposed=false,loaded=false,loading=false,offset=0;
 const notice=(message)=>{section.querySelector('[role=status]').textContent=message;};
 async function call(path,options={}){if(!canManage()){dispose();throw Error('관리자 권한이 필요합니다.');}return api('/v2/ai-classification'+path,{...options,signal:abort.signal});}
 async function load(){if(loading)return;loading=true;try{const d=await call('/research?album_id='+encodeURIComponent(albumId)+'&offset='+offset);if(disposed)return;section.querySelector('[data-research-items]').innerHTML=researchMarkup(d);section.querySelector('[data-research-next]').hidden=!d.has_more;loaded=true;notice('저장된 연구 기록 · AI 제안이며 운영 메타데이터에 반영되지 않습니다.');}finally{loading=false;}}
 async function guard(fn){try{await fn();}catch(e){if(!disposed&&e.name!=='AbortError')notice(e.message||'기록 조회 실패');}}
 section.addEventListener('toggle',()=>{if(section.open&&!loaded)void guard(load);},{signal:abort.signal});
 section.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;void guard(async()=>{
  if(b.hasAttribute('data-research-refresh')){offset=0;await load();}
  if(b.hasAttribute('data-research-next')){offset+=20;await load();}
  if(b.hasAttribute('data-deep')){const d=await call('/research-request',{body:{album_id:albumId}});notice(d.state==='cached'?'동일 입력의 심층 연구가 이미 저장되어 있습니다.':'심층 연구를 등록했습니다. AI 관리 화면에서 별도로 시작하세요.');}
  if(b.dataset.researchState){await call('/research-review',{body:{id:b.dataset.id,action:b.dataset.researchState}});await load();}
 });},{signal:abort.signal});
 section.addEventListener('submit',e=>{const form=e.target;e.preventDefault();void guard(async()=>{const f=new FormData(form);let body={id:form.dataset.id};if(form.hasAttribute('data-research-edit'))body={...body,action:'revise',content:JSON.parse(f.get('content'))};else body={...body,action:'source',field:f.get('field'),url:f.get('url'),title:f.get('title'),attest_checked:f.get('attest')==='on',...(verifiedFields.includes(f.get('field'))?{verified_value:(()=>{const v=f.get('verified_value').trim();return /(?:year|release_attributes)$/.test(f.get('field'))?JSON.parse(v):v;})()}: {})};await call('/research-review',{body});offset=0;await load();});},{signal:abort.signal});
 function auth(){if(!canManage())dispose();}
 function dispose(){if(disposed)return;disposed=true;abort.abort();section.remove();doc.defaultView?.removeEventListener('vinyl-account-change',auth);doc.defaultView?.removeEventListener('vinyl-approval-change',auth);}
 doc.defaultView?.addEventListener('vinyl-account-change',auth);doc.defaultView?.addEventListener('vinyl-approval-change',auth);return dispose;
}
